    14  /*----------------------------------------------------------*/
    15  /*
    16     readline()
    17     Read the next line in the postscript file.
    18     Automatically skip over data (as indicated by
    19     %%BeginBinary/%%EndBinary or %%BeginData/%%EndData
    20     comments.)
    21     Also, skip over included documents (as indicated by
    22     %%BeginDocument/%%EndDocument comments.)
    23  */
    24  /*----------------------------------------------------------*/
    25
    26  static char * readline (fd, enddoseps, lineP, positionP, line_lenP)
    27     FileData fd;
    28     long enddoseps;
    29     char **lineP;
    30     long *positionP;
    31     unsigned int *line_lenP;
    32  {
    33     unsigned int nbytes=0;
    34     int skipped=0;
    35     int nesting_level=0;
    36     char *line;
    37
    38     BEGINMESSAGE(readline)
    39
    40     if (positionP) *positionP = FD_FILEPOS;
    41     if (positionP && enddoseps) {
    42         if (*positionP >= enddoseps)
    43             return NULL;    /* don't read any more, we have reached end of dos eps section */
    44     }
    45
    46     line = ps_io_fgetchars(fd,-1);
    47     if (!line) {
    48        INFMESSAGE(could not get line)
    49        *line_lenP = 0;
    50        *lineP     = empty_string;
    51        ENDMESSAGE(readline)
    52        return(NULL);
    53     }
    54
    55     *line_lenP = FD_LINE_LEN;
    56
    57  #define IS_COMMENT(comment)                             \
    58             (DSCcomment(line) && iscomment(line+2,(comment)))
    59  #define IS_BEGIN(comment)                               \
    60             (iscomment(line+7,(comment)))
    61  #define IS_END(comment)                         \
    62             (iscomment(line+5,(comment)))
    63  #define SKIP_WHILE(cond)                                \
    64             while (readline(fd, enddoseps, &line, NULL, &nbytes) && (cond)) *line_lenP += nbytes;        \
    65             skipped=1;
    66  #define SKIP_UNTIL_1(comment) {                         \
    67             INFMESSAGE(skipping until comment)           \
    68             SKIP_WHILE((!IS_COMMENT(comment)))           \
    69             INFMESSAGE(completed skipping until comment) \
    70          }
    71  #define SKIP_UNTIL_2(comment1,comment2) {               \
    72             INFMESSAGE(skipping until comment1 or comment2)\
    73             SKIP_WHILE((!IS_COMMENT(comment1) && !IS_COMMENT(comment2)))\
    74             INFMESSAGE(completed skipping until comment1 or comment2)\
    75          }
    76
    77  #if 0
    78     if ((scanstyle&SCANSTYLE_MISSING_BEGINDOCUMENT) &&
    79         (line[0] == '%') &&
    80         (*line_lenP > 11) &&
    81         (iscomment(line,"%!PS-Adobe-") || iscomment(line + 1,"%!PS-Adobe-"))) {
    82       char *c=line+11;
    83       while (*c && !isspace(*c)) c++;
    84       if (isspace(*c)) while (*c && isspace(*c)) c++;
    85       /* don't skip EPSF files */
    86         printf("line in question: %s\n",line);
    87       if (strncmp(c,"EPSF",4)) {
    88         printf("skipping starts here: %s\n",line);
    89         SKIP_UNTIL_1("EOF")
    90         *line_lenP += nbytes;
    91         readline(fd, enddoseps, &line, NULL, &nbytes);
    92         printf("skipping ends here: %s\n",line);
    93       }
    94     }
    95     else
    96  #endif
    97     if  (!IS_COMMENT("Begin"))     {} /* Do nothing */
    98     else if IS_BEGIN("Document:")  {  /* Skip the EPS without handling its content */
    99         nesting_level=1;
   100         line = ps_io_fgetchars(fd,-1);
   101         if (line) *line_lenP += FD_LINE_LEN;
   102         while (line) {
   103             if (IS_COMMENT("Begin") && IS_BEGIN("Document:"))
   104                 nesting_level++;
   105             else if (IS_COMMENT("End") && IS_END("Document"))
   106                 nesting_level--;
   107             if (nesting_level == 0) break;
   108             line = ps_io_fgetchars(fd,-1);
   109             if (line) *line_lenP += FD_LINE_LEN;
   110         }
   111     }
   112     else if IS_BEGIN("Feature:")   SKIP_UNTIL_1("EndFeature")
   113  #ifdef USE_ACROREAD_WORKAROUND
   114     else if IS_BEGIN("File")       SKIP_UNTIL_2("EndFile","EOF")
   115  #else
   116     else if IS_BEGIN("File")       SKIP_UNTIL_1("EndFile")
   117  #endif
   118     else if IS_BEGIN("Font")       SKIP_UNTIL_1("EndFont")
   119     else if IS_BEGIN("ProcSet")    SKIP_UNTIL_1("EndProcSet")
   120     else if IS_BEGIN("Resource")   SKIP_UNTIL_1("EndResource")
   121     else if IS_BEGIN("Data:")      {
   122        int  num;
   123        char text[101];
   124        INFMESSAGE(encountered "BeginData:")
   125        if (FD_LINE_LEN > 100) FD_BUF[100] = '\0';
   126        text[0] = '\0';
   127        if (sscanf(line+length("%%BeginData:"), "%d %*s %100s", &num, text) >= 1) {
   128           if (strcmp(text, "Lines") == 0) {
   129              INFIMESSAGE(number of lines to skip:,num)
   130              while (num) {
   131                 line = ps_io_fgetchars(fd,-1);
   132                 if (line) *line_lenP += FD_LINE_LEN;
   133                 num--;
   134              }
   135           } else {
   136              int read_chunk_size = LINE_CHUNK_SIZE;
   137              INFIMESSAGE(number of chars to skip:,num)
   138              while (num>0) {
   139                 if (num <= LINE_CHUNK_SIZE) read_chunk_size=num;
   140                 line = ps_io_fgetchars(fd,read_chunk_size);
   141                 if (line) *line_lenP += FD_LINE_LEN;
   142                 num -= read_chunk_size;
   143              }
   144           }
   145        }
   146        SKIP_UNTIL_1("EndData")
   147     }
   148     else if IS_BEGIN("Binary:") {
   149        int  num;
   150        INFMESSAGE(encountered "BeginBinary:")
   151        if (sscanf(line+length("%%BeginBinary:"), "%d", &num) == 1) {
   152           int read_chunk_size = LINE_CHUNK_SIZE;
   153           INFIMESSAGE(number of chars to skip:,num)
   154           while (num>0) {
   155              if (num <= LINE_CHUNK_SIZE) read_chunk_size=num;
   156              line = ps_io_fgetchars(fd,read_chunk_size);
   157              if (line) *line_lenP += FD_LINE_LEN;
   158              num -= read_chunk_size;
   159           }
   160           SKIP_UNTIL_1("EndBinary")
   161        }
   162     }
   163
   164     if (skipped) {
   165        INFMESSAGE(skipped lines)
   166        *line_lenP += nbytes;
   167        *lineP = skipped_line;
   168     } else {
   169        *lineP = FD_BUF+FD_LINE_BEGIN;
   170     }
   171
   172     ENDMESSAGE(readline)
   173     return(FD_BUF+FD_LINE_BEGIN);
   174  }
